SELECT kind, temporal, functional, inverse_functional, is_transitive,
       is_symmetric, is_asymmetric, is_irreflexive, inverse_of, sub_property_of
  FROM relation_types WHERE id = #{id} AND kb_id = #{kbId}

WITH RECURSIVE up(id) AS (
    SELECT unnest(#{parents,typeHandler=tech.seexun.jknow.store.typehandler.UuidArrayTypeHandler}::uuid[])
    UNION
    SELECT p.parent_id FROM entity_type_parents p JOIN up ON p.child_id = up.id
)
SELECT count(*) FROM up WHERE id = #{childId}

mapper.update:
UPDATE entity_types SET label = #{label}, color = COALESCE(#{color}, color), shape = #{shape},
        description = #{description}, updated_at = now()
 WHERE id = #{id} AND kb_id = #{kbId}
